<?php require_once '../includes/auth.php';require_once '../config/koneksi.php';$id=(int)($_GET['id']??0);$st=$conn->prepare('SELECT nama_kelas FROM kelas WHERE id_kelas=?');$st->bind_param('i',$id);$st->execute();$r=$st->get_result()->fetch_assoc();if($r){$c=$conn->prepare('SELECT COUNT(*) n FROM siswa WHERE kelas=?');$c->bind_param('s',$r['nama_kelas']);$c->execute();if((int)$c->get_result()->fetch_assoc()['n']===0){$d=$conn->prepare('DELETE FROM kelas WHERE id_kelas=?');$d->bind_param('i',$id);$d->execute();}}header('Location: index.php');exit;?>